{
	u16 hash_alg = get_unaligned_be16(name);

	switch (hash_alg) {
	case TPM_ALG_SHA1:
		return SHA1_DIGEST_SIZE + 2;
	case TPM_ALG_SHA256:
		return SHA256_DIGEST_SIZE + 2;
	case TPM_ALG_SHA384:
		return SHA384_DIGEST_SIZE + 2;
	case TPM_ALG_SHA512:
		return SHA512_DIGEST_SIZE + 2;
	default:
		pr_warn("tpm: unsupported name algorithm: 0x%04x\n", hash_alg);
		return -EINVAL;
	}
}

